From e33232ba31c46f275ab53b30301e0f30f4f5f531 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:18:06 +0100
Subject: [PATCH] microphone indicator: show it while all microphones are muted

The indicator only appeared while an app was recording, so muting the mics
with the shortcut left no sign of it in the tray. Keep it shown whenever all
microphones are muted, but not on systems that have no microphone at all.

BUG: 501782
---
 src/qml/microphoneindicator.cpp | 10 ++++++----
 1 file changed, 6 insertions(+), 4 deletions(-)

diff --git a/src/qml/microphoneindicator.cpp b/src/qml/microphoneindicator.cpp
index 4cfb996e..434fd5a2 100644
--- a/src/qml/microphoneindicator.cpp
+++ b/src/qml/microphoneindicator.cpp
@@ -92,7 +92,9 @@ void MicrophoneIndicator::scheduleUpdate()
 void MicrophoneIndicator::update()
 {
     const auto apps = recordingApplications();
-    if (apps.isEmpty()) {
+    const bool allMuted = m_sourceModel->rowCount() > 0 && muted();
+
+    if (apps.isEmpty() && !allMuted) {
         m_showOsdOnUpdate = false;
         delete m_sni;
         m_sni = nullptr;
@@ -138,8 +140,6 @@ void MicrophoneIndicator::update()
         m_sni->setStandardActionsEnabled(false);
     }

-    const bool allMuted = muted();
-
     QString iconName;
     if (allMuted) {
         iconName = QStringLiteral("microphone-sensitivity-muted");
@@ -164,9 +164,11 @@ void MicrophoneIndicator::update()
         iconName.append(QStringLiteral("-rtl"));
     }

+    const QString toolTipSubText = apps.isEmpty() ? QString() : toolTipForApps(apps);
+
     m_sni->setTitle(i18n("Microphone"));
     m_sni->setIconByName(iconName);
-    m_sni->setToolTip(QIcon::fromTheme(iconName), allMuted ? i18n("Microphone Muted") : i18n("Microphone"), toolTipForApps(apps));
+    m_sni->setToolTip(QIcon::fromTheme(iconName), allMuted ? i18n("Microphone Muted") : i18n("Microphone"), toolTipSubText);

     if (m_muteAction) {
         m_muteAction->setChecked(allMuted);
-- 
